import { getRouteApi, Link } from '@tanstack/react-router'
import { MobileTopBar } from '@/components/layout/mobile-nav'
import { useDocumentTitle } from '@/hooks/use-document-title'

const routeApi = getRouteApi('/explorador/tx/$hash')
const TX_HASH = /^0x[0-9a-f]{64}$/i

/** Simulated explorer: the hash is generated by the mock and does not exist on a real network. */
export function ExplorerPage() {
  const { hash } = routeApi.useParams()
  useDocumentTitle('Transação (simulada) | Kurio')
  const valid = TX_HASH.test(hash)

  return (
    <>
      <MobileTopBar title="Explorador" />
      <section className="container-site py-12">
        <p className="text-sm tracking-[0.1em] text-brand">EXPLORADOR SIMULADO</p>
        <h1 className="mt-2 text-2xl font-bold">Detalhes da transação</h1>
        <div className="mt-6 rounded-[4px] bg-surface p-6 text-sm">
          {valid ? (
            <dl className="grid gap-3 sm:grid-cols-[160px_1fr]">
              <dt className="text-muted-foreground">Hash</dt>
              <dd className="font-bold break-all">{hash}</dd>
              <dt className="text-muted-foreground">Status</dt>
              <dd className="text-success">Sucesso (simulado)</dd>
              <dt className="text-muted-foreground">Observação</dt>
              <dd>Esta referência foi gerada pela simulação do marketplace e não corresponde a uma transação real.</dd>
            </dl>
          ) : (
            <p role="alert">Hash de transação inválido.</p>
          )}
        </div>
        <Link to="/" className="mt-6 inline-block text-brand hover:underline">
          Voltar ao início
        </Link>
      </section>
    </>
  )
}
